css:
.tiersim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #211a2e;
    background: linear-gradient(160deg, #f4f1fb 0%, #ede7f6 100%);
    border-radius: 18px;
}

.tiersim-container * {
    box-sizing: border-box;
}

.tiersim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2d1b59 0%, #4b2e85 50%, #6c3fb0 100%);
    color: #f7f2ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(45, 27, 89, 0.32);
}

.tiersim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.tiersim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e9d6ff;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.tiersim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ece1fb;
}

.tiersim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3c2a66;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.tiersim-period-counter #currentDay,
.tiersim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2d1b59;
}

.tiersim-round-name {
    background: #e3d6f7;
    color: #4b2e85;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.tiersim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3412;
    background: #fde7d8;
    padding: 4px 12px;
    border-radius: 999px;
}

.tiersim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.tiersim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d6f0;
    box-shadow: 0 4px 14px rgba(45, 27, 89, 0.06);
    border-top: 4px solid #6c3fb0;
}

.tiersim-card-margin { border-top-color: #0e7c5a; }
.tiersim-card-revenue { border-top-color: #b07d12; }
.tiersim-card-fairness { border-top-color: #4b2e85; }
.tiersim-card-cannib { border-top-color: #c0392b; }

.tiersim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6f6285;
}

.tiersim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2d1b59;
}

.tiersim-card-margin .tiersim-value { color: #0e7c5a; }
.tiersim-card-revenue .tiersim-value { color: #b07d12; }
.tiersim-card-fairness .tiersim-value { color: #4b2e85; }
.tiersim-card-cannib .tiersim-value { color: #c0392b; }

.tiersim-sublabel {
    font-size: 0.76rem;
    color: #7c6f92;
    line-height: 1.35;
}

.tiersim-margin-hit .tiersim-value { color: #0e7c5a; }
.tiersim-margin-miss .tiersim-value { color: #c0392b; }
.tiersim-fairness-hit .tiersim-value { color: #0e7c5a; }
.tiersim-fairness-miss .tiersim-value { color: #c0392b; }
.tiersim-cannib-high { border-top-color: #c0392b; }
.tiersim-cannib-high .tiersim-value { color: #c0392b; }
.tiersim-cannib-low .tiersim-value { color: #0e7c5a; }

.tiersim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2d1b59;
    color: #f1e9fb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.tiersim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.tiersim-budget-over #budgetDisplay {
    color: #ff8f6b;
}

.tiersim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6c3fb0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(45, 27, 89, 0.05);
}

.tiersim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.tiersim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2d1b59;
    margin-bottom: 6px;
}

.tiersim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a2f4d;
}

.tiersim-briefing-text strong { color: #0e7c5a; }
.tiersim-briefing-text em { color: #9a3412; font-style: italic; }

.tiersim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d6f0;
    box-shadow: 0 4px 14px rgba(45, 27, 89, 0.06);
}

.tiersim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2d1b59;
    border-bottom: 2px solid #ece4f8;
    padding-bottom: 8px;
}

.tiersim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #34254f;
    margin: 14px 0 6px;
}

.tiersim-container select,
.tiersim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdbde8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf7fe;
    color: #211a2e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.tiersim-container select:focus,
.tiersim-container input[type="number"]:focus {
    outline: none;
    border-color: #6c3fb0;
    box-shadow: 0 0 0 3px rgba(108, 63, 176, 0.16);
}

.tiersim-container select option {
    background-color: #ffffff;
    color: #211a2e;
}

.tiersim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6c3fb0;
}

.tiersim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4b2e85;
    margin-top: 4px;
}

.tiersim-range-readout span:last-child {
    color: #0e7c5a;
    font-weight: 800;
}

.tiersim-hint {
    font-size: 0.8rem;
    color: #7c6f92;
    margin-top: 4px;
    line-height: 1.4;
}

.tiersim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.tiersim-container .btn-primary {
    background: linear-gradient(135deg, #4b2e85 0%, #6c3fb0 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(75, 46, 133, 0.30);
}

.tiersim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.tiersim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdbde8;
    color: #6f6285;
}

.tiersim-coach {
    background: #2d1b59;
    color: #f1e9fb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(45, 27, 89, 0.24);
}

.tiersim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #c9a9f0;
    margin-bottom: 8px;
}

.tiersim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.tiersim-coach-body strong { color: #ffd98a; }
.tiersim-coach-body em { color: #ffb59a; font-style: italic; }

.tiersim-history,
.tiersim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d6f0;
    box-shadow: 0 4px 14px rgba(45, 27, 89, 0.06);
}

.tiersim-history h3,
.tiersim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2d1b59;
}

.tiersim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #34254f;
}

.tiersim-container table#usfHistoryTable th {
    background: #f1eafa;
    color: #2d1b59;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d5f4;
}

.tiersim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f1ebf8;
}

.tiersim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7fe;
}

.tiersim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .tiersim-container {
        padding: 14px;
    }
    .tiersim-header h1 {
        font-size: 1.7rem;
    }
    .tiersim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .tiersim-value {
        font-size: 2rem;
    }
    .tiersim-clock {
        margin-left: 0;
    }
    .tiersim-period-counter {
        font-size: 0.88rem;
    }
    .tiersim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .tiersim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, tiersim) ---- */
.tiersim-completion { padding: 8px 4px 4px; }
.tiersim-cm-head { text-align: center; margin-bottom: 16px; }
.tiersim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #6f5aa8; }
.tiersim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #9484bf; }
.tiersim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #2c2838; }
.tiersim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.tiersim-cm-yes { background: rgba(90,140,70,0.15); color: #497a2f; border: 1px solid rgba(90,140,70,0.5); }
.tiersim-cm-no { background: rgba(176,66,50,0.12); color: #a53f2c; border: 1px solid rgba(176,66,50,0.45); }
.tiersim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.tiersim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(111,90,168,0.08); border: 1px solid rgba(111,90,168,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.tiersim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6152a0; }
.tiersim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #6d6680; text-transform: uppercase; letter-spacing: 0.03em; }
.tiersim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #2c2838; }
.tiersim-cm-insights { margin: 0; padding-left: 20px; }
.tiersim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3b3548; }

