(function() {
    'use strict';

    class TierAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Price the Tier`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Brücke Mobility GmbH).
            this.START_MARGIN = 34;       // blended contribution margin %, single flat plan
            this.TARGET_MARGIN = 39;      // CFO target +5 points
            this.START_FAIRNESS = 49;     // fell from 72 after the leak
            this.TARGET_FAIRNESS = 65;    // recover above 65
            this.TARGET_REVENUE = 8;      // CFO revenue-lift target, %
            this.START_CANNIB = 35;       // buy-down risk, 0-100 (lower better)
            this.BUDGET_CAP = 2400;       // launch & comms budget, in thousands EUR (€2.4M)
            this.FLAT_PRICE = 42;         // current flat plan, €/month
            this.ENTRANT_PRICE = 35;      // national entrant flat plan, €/month
        }

        // Locale-aware EUR formatting. EN: "€2.4M" (symbol before). ES: "2,4 M€" (symbol after).
        _fmtMoneyK(valueK) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const millions = valueK / 1000;
            const es = lang === `es`;
            let num;
            if (Math.abs(millions) >= 1 || valueK === 0) {
                num = (Math.round(millions * 10) / 10).toFixed(1);
                if (es) {
                    num = num.replace(`.`, `,`);
                    return num + ` M€`;
                }
                return `€` + num + `M`;
            }
            // sub-million: show thousands
            const k = Math.round(valueK);
            if (es) return k.toLocaleString(`de-DE`) + ` k€`;
            return `€` + k.toLocaleString(`en-US`) + `k`;
        }

        _fmtPrice(value) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const v = Math.round(value);
            if (lang === `es`) return v + ` €`;
            return `€` + v;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: this.START_MARGIN,
                    revenue: 0,
                    fairness: this.START_FAIRNESS,
                    cannib: this.START_CANNIB,
                    budgetUsed: 0,
                    overBudget: false,
                    marginHistory: [this.START_MARGIN],
                    revenueHistory: [0],
                    fairnessHistory: [this.START_FAIRNESS],
                    cannibHistory: [this.START_CANNIB],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately MIDDLING — a click-through must not auto-win.
                state.decisions = {
                    underpriced: `commuters`,
                    metric: `cost`,
                    rigor: 50,
                    tiers: `manytiers`,
                    entryPrice: 33,
                    topPrice: 55,
                    gap: 50,
                    fenceType: `mixed`,
                    commitment: `none`,
                    arbitrage: 50,
                    narrative: `silent`,
                    transition: `nochange`,
                    competitive: `ignore`,
                    comms: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const up = document.getElementById(`underpricedInput`);
                const met = document.getElementById(`metricInput`);
                const rg = document.getElementById(`rigorInput`);
                if (up) decisions.underpriced = up.value;
                if (met) decisions.metric = met.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const ti = document.getElementById(`tiersInput`);
                const ep = document.getElementById(`entryPriceInput`);
                const tp = document.getElementById(`topPriceInput`);
                const gp = document.getElementById(`gapInput`);
                if (ti) decisions.tiers = ti.value;
                if (ep) decisions.entryPrice = parseFloat(ep.value);
                if (tp) decisions.topPrice = parseFloat(tp.value);
                if (gp) decisions.gap = parseInt(gp.value, 10);
                if (!Number.isFinite(decisions.entryPrice) || decisions.entryPrice < 28 || decisions.entryPrice > 42) {
                    warn(`warn_entry_range`); return false;
                }
                if (!Number.isFinite(decisions.topPrice) || decisions.topPrice < 45 || decisions.topPrice > 80) {
                    warn(`warn_top_range`); return false;
                }
                if (decisions.topPrice <= decisions.entryPrice) {
                    warn(`warn_top_above_entry`); return false;
                }
                if (!Number.isFinite(decisions.gap) || decisions.gap < 0 || decisions.gap > 100) {
                    warn(`warn_gap_range`); return false;
                }
            } else if (round === 3) {
                const ft = document.getElementById(`fenceTypeInput`);
                const cm = document.getElementById(`commitmentInput`);
                const ab = document.getElementById(`arbitrageInput`);
                if (ft) decisions.fenceType = ft.value;
                if (cm) decisions.commitment = cm.value;
                if (ab) decisions.arbitrage = parseInt(ab.value, 10);
                if (!Number.isFinite(decisions.arbitrage) || decisions.arbitrage < 0 || decisions.arbitrage > 100) {
                    warn(`warn_arbitrage_range`); return false;
                }
            } else if (round === 4) {
                const na = document.getElementById(`narrativeInput`);
                const tr = document.getElementById(`transitionInput`);
                const cp = document.getElementById(`competitiveInput`);
                const co = document.getElementById(`commsInput`);
                if (na) decisions.narrative = na.value;
                if (tr) decisions.transition = tr.value;
                if (cp) decisions.competitive = cp.value;
                if (co) decisions.comms = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.comms) || decisions.comms < 0 || decisions.comms > 100) {
                    warn(`warn_comms_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: margin (pts), revenue lift (pts), fairness (pts), cannib risk (pts, +=worse).
            let mD = 0, rD = 0, fD = 0, cD = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the customers — diagnose who the flat €42 plan under-prices, anchor on value.
                if (d.underpriced === `power`) { mD += 0.8; rD += 1.0; coachKey = `coach_r1_power`; }
                else if (d.underpriced === `students`) { mD -= 1.0; cD += 5; coachKey = `coach_r1_students`; }
                else if (d.underpriced === `commuters`) { mD -= 0.3; coachKey = `coach_r1_commuters`; }
                else { mD -= 0.3; coachKey = `coach_r1_families`; }

                if (d.metric === `value`) {
                    fD += 3; mD += 0.6; rD += 0.8;
                    if (d.underpriced === `power`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.metric === `personalised`) {
                    fD -= 8; cD += 4; mD += 0.4; spend += 300; coachKey = `coach_r1_personalised`;
                } else if (d.metric === `discountall`) {
                    mD -= 1.2; rD += 0.6; cD += 5; coachKey = `coach_r1_discountall`;
                } else {
                    mD += 0.2; fD -= 1; coachKey = `coach_r1_cost`;
                }

                if (d.rigor >= 60) { mD += 0.5; rD += 0.4; fD += 2; }
                else if (d.rigor <= 25) { mD -= 0.6; fD -= 2; coachKey = `coach_r1_norigor`; }

                spend += 120; // segmentation & WTP study
                summaryKey = (d.underpriced === `power` && d.metric === `value`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design the tier ladder — prices and the gap discipline that prevents buy-down.
                switch (d.tiers) {
                    case `goodbetterbest`: mD += 1.6; rD += 2.2; coachKey = `coach_r2_gbb`; break;
                    case `flat`: mD -= 1.0; rD -= 1.2; fD -= 1; coachKey = `coach_r2_flat`; break;
                    case `pricewar`: mD -= 2.6; rD += 1.6; fD -= 3; cD += 7; coachKey = `coach_r2_pricewar`; break;
                    case `manytiers`: mD += 0.3; rD += 0.3; cD += 9; fD -= 2; spend += 200; coachKey = `coach_r2_manytiers`; break;
                }

                const ep = d.entryPrice;
                if (ep >= 35 && ep <= 38) { mD += 0.9; rD += 1.1; fD += 1.5; }
                else if (ep < 34) { mD -= 2.2; rD += 2.0; fD -= 3; cD += 4; coachKey = `coach_r2_entrylow`; }
                else if (ep > 38) { rD -= 1.3; cD += 3; coachKey = `coach_r2_entryhigh`; }
                else { mD += 0.3; rD += 0.3; }

                const tp = d.topPrice;
                if (tp >= 58 && tp <= 66) { mD += 1.8; rD += 1.8; }
                else if (tp < 52) { mD -= 1.2; rD -= 0.8; coachKey = `coach_r2_toplow`; }
                else if (tp > 70) { mD += 1.8; rD += 1.2; fD -= 10; cD += 2; coachKey = `coach_r2_tophigh`; }
                else { mD += 0.9; rD += 0.8; }

                if (d.gap >= 60) { cD -= 10; mD += 0.8; if (d.tiers === `goodbetterbest`) coachKey = `coach_r2_gapgood`; }
                else if (d.gap <= 30) { cD += 18; mD -= 3.2; rD -= 1.5; coachKey = `coach_r2_gaplow`; }
                else { cD -= 2; }

                spend += 420; // versioning & packaging build
                summaryKey = (d.tiers === `goodbetterbest` && d.gap >= 60 && ep >= 35 && ep <= 38 && tp >= 58 && tp <= 66) ? `sum_r2_good`
                    : (d.tiers === `pricewar` || ep < 34 ? `sum_r2_war` : `sum_r2_weak`);
            } else if (round === 3) {
                // Build the fences — leak-proof AND fair. Data-based fences repeat the scandal.
                switch (d.fenceType) {
                    case `controllable`: fD += 7; cD -= 8; mD += 0.8; coachKey = `coach_r3_controllable`; break;
                    case `data`: fD -= 15; cD -= 4; spend += 250; coachKey = `coach_r3_data`; break;
                    case `nofence`: cD += 15; mD -= 2.2; coachKey = `coach_r3_nofence`; break;
                    case `mixed`: fD -= 4; cD -= 3; coachKey = `coach_r3_mixed`; break;
                }

                switch (d.commitment) {
                    case `annualoffpeak`: cD -= 7; mD += 1.0; fD += 2; break;
                    case `lockin`: fD -= 5; cD -= 5; coachKey = `coach_r3_lockin`; break;
                    case `none`: cD += 6; break;
                }

                if (d.arbitrage >= 60) { cD -= 7; mD += 0.6; }
                else if (d.arbitrage <= 25) { cD += 8; mD -= 1.0; coachKey = `coach_r3_noarb`; }

                spend += 350; // fence implementation
                summaryKey = (d.fenceType === `controllable` && d.commitment === `annualoffpeak`) ? `sum_r3_good`
                    : (d.fenceType === `data` ? `sum_r3_unfair` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend fairness & launch — narrative, transition, competitive response, comms.
                switch (d.narrative) {
                    case `transparent`: fD += 10; coachKey = `coach_r4_transparent`; break;
                    case `silent`: fD -= 8; coachKey = `coach_r4_silent`; break;
                    case `spin`: fD -= 13; coachKey = `coach_r4_spin`; break;
                }

                switch (d.transition) {
                    case `grandfather`: fD += 7; rD -= 0.5; cD -= 2; break;
                    case `abrupt`: fD -= 10; rD += 0.8; coachKey = `coach_r4_abrupt`; break;
                    case `nochange`: fD -= 4; break;
                }

                switch (d.competitive) {
                    case `valueversion`: mD += 0.8; rD += 1.2; fD += 2; coachKey = (d.narrative === `transparent`) ? `coach_r4_valueversion` : coachKey; break;
                    case `matchprice`: mD -= 2.8; rD += 0.8; fD -= 2; cD += 4; coachKey = `coach_r4_matchprice`; break;
                    case `ignore`: rD -= 1.8; fD -= 1; coachKey = `coach_r4_ignore`; break;
                }

                if (d.comms >= 60) { fD += 5; }
                else if (d.comms <= 25) { fD -= 4; }
                spend += Math.round(d.comms * 14); // campaign spend, up to €1.4M

                summaryKey = (d.narrative === `transparent` && d.transition === `grandfather` && d.competitive === `valueversion`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            ds.overBudget = ds.budgetUsed > this.BUDGET_CAP;

            // Apply deltas with clamps that leave headroom (no early saturation).
            ds.margin = Math.max(20, Math.min(60, ds.margin + mD));
            ds.revenue = Math.max(-20, Math.min(40, ds.revenue + rD));
            ds.fairness = Math.max(0, Math.min(100, ds.fairness + fD));
            ds.cannib = Math.max(0, Math.min(100, ds.cannib + cD));

            ds.marginHistory.push(Math.round(ds.margin * 10) / 10);
            ds.revenueHistory.push(Math.round(ds.revenue * 10) / 10);
            ds.fairnessHistory.push(Math.round(ds.fairness));
            ds.cannibHistory.push(Math.round(ds.cannib));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                margin: Math.round(ds.margin * 10) / 10,
                marginDelta: Math.round(mD * 10) / 10,
                revenue: Math.round(ds.revenue * 10) / 10,
                revenueDelta: Math.round(rD * 10) / 10,
                fairness: Math.round(ds.fairness),
                fairnessDelta: Math.round(fD),
                cannib: Math.round(ds.cannib),
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

