        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const margin = Math.round(ds.margin * 10) / 10;
            const revenue = Math.round(ds.revenue * 10) / 10;
            const fairness = Math.round(ds.fairness);
            const cannib = Math.round(ds.cannib);
            const marginScore = Math.max(0, Math.min(100, (margin - 30) / (46 - 30) * 100));
            const revScore = Math.max(0, Math.min(100, (revenue + 4) / (16 + 4) * 100));
            const cannScore = 100 - cannib;
            let composite = Math.round(marginScore * 0.30 + revScore * 0.25 + fairness * 0.30 + cannScore * 0.15);
            if (ds.overBudget) composite -= 12;
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="tiersim-cm-badge tiersim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="tiersim-cm-badge tiersim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.overBudget) failBadge += ` <span class="tiersim-cm-badge tiersim-cm-no">` + T(`cm_overbudget`) + `</span>`;
            if (Math.round(s.cannib || 0) >= 50) failBadge += ` <span class="tiersim-cm-badge tiersim-cm-no">` + T(`cm_cannib`) + `</span>`;
            if (s.hitMargin && s.hitRevenue && !s.hitFairness) failBadge += ` <span class="tiersim-cm-badge tiersim-cm-no">` + T(`cm_trustlost`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="tiersim-cm-metric"><span class="tiersim-cm-mv">` + Number(s.margin || 0).toFixed(1) + `%</span><span class="tiersim-cm-ml">` + T(`cm_m_margin`) + `</span></div>`
                + `<div class="tiersim-cm-metric"><span class="tiersim-cm-mv">` + Number(s.revenue || 0).toFixed(1) + `%</span><span class="tiersim-cm-ml">` + T(`cm_m_revenue`) + `</span></div>`
                + `<div class="tiersim-cm-metric"><span class="tiersim-cm-mv">` + Math.round(s.fairness || 0) + `</span><span class="tiersim-cm-ml">` + T(`cm_m_fairness`) + `</span></div>`
                + `<div class="tiersim-cm-metric"><span class="tiersim-cm-mv">` + Math.round(s.cannib || 0) + `</span><span class="tiersim-cm-ml">` + T(`cm_m_cannib`) + `</span></div>`;
            return ``
                + `<div class="tiersim-completion">`
                +   `<div class="tiersim-cm-head">`
                +     `<div class="tiersim-cm-score">` + score + `<span class="tiersim-cm-score-max">/100</span></div>`
                +     `<div class="tiersim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="tiersim-cm-metrics">` + metrics + `</div>`
                +   `<div class="tiersim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="tiersim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const margin = Math.round(ds.margin * 10) / 10;
            const revenue = Math.round(ds.revenue * 10) / 10;
            const fairness = Math.round(ds.fairness);
            const cannib = Math.round(ds.cannib);

            const hitMargin = margin >= this.TARGET_MARGIN;
            const hitRevenue = revenue >= this.TARGET_REVENUE;
            const hitFairness = fairness > this.TARGET_FAIRNESS;
            const overBudget = ds.overBudget;

            const composite = this._composite(ds);

            let performanceKey = `grade_backlash`;
            if (hitMargin && hitRevenue && hitFairness && !overBudget && composite >= 80) performanceKey = `grade_ladder`;
            else if (hitMargin && hitRevenue && hitFairness) performanceKey = `grade_targets`;
            else if (hitMargin && hitRevenue && !hitFairness) performanceKey = `grade_marginwon`;
            else if (hitFairness && !hitMargin) performanceKey = `grade_fairsub`;
            else if (margin > this.START_MARGIN + 2 || fairness > this.START_FAIRNESS + 6) performanceKey = `grade_improving`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitMargin && hitRevenue && hitFairness && !overBudget) insights.push(window.mySimulation.t(`insight_full`));
            else if (hitMargin && hitRevenue && !hitFairness) insights.push(window.mySimulation.t(`insight_marginonly`));
            else if (!hitMargin && hitFairness) insights.push(window.mySimulation.t(`insight_fairnotmargin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (cannib >= 50) insights.push(window.mySimulation.t(`insight_cannib`));
            if (fairness <= this.TARGET_FAIRNESS) insights.push(window.mySimulation.t(`insight_lowfairness`));
            if (overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (hitMargin && hitRevenue && hitFairness && cannib < 25) insights.push(window.mySimulation.t(`insight_selfselect`));

            return {
                margin: margin,
                revenue: revenue,
                fairness: fairness,
                cannib: cannib,
                hitMargin: hitMargin,
                hitRevenue: hitRevenue,
                hitFairness: hitFairness,
                overBudget: overBudget,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (hitMargin && hitRevenue && hitFairness && !overBudget && composite >= 80),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.fairness <= 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_fairness`);
            if (ds.cannib >= 55) return window.mySimulation.t(`hint_cannib`);
            if (state.currentPeriod >= 3 && ds.margin < 36) return window.mySimulation.t(`hint_margin`);
            if (ds.margin >= this.TARGET_MARGIN && ds.fairness > this.TARGET_FAIRNESS && ds.revenue >= this.TARGET_REVENUE) return window.mySimulation.t(`hint_strong`);
            return null;
        }

